reference_solution:
def maximum_distinct_after_adjustment(nums,k):
    previous=float('-inf');answer=0
    for value in sorted(nums):
        chosen=min(value+k,max(value-k,previous+1))
        if chosen>previous:answer+=1;previous=chosen
    return answer

